// Core/Networking/APIError.swift
enum APIError: Error, Equatable, Sendable {
    case networkUnavailable
    case httpError(statusCode: Int)
    case decodingFailed
    case unauthorized
    case timeout
    case unknown(String)

    var isRetryable: Bool {
        switch self {
        case .networkUnavailable, .timeout:
            return true
        case .httpError(let code):
            return code >= 500
        default:
            return false
        }
    }
}

// Domain/Article/ArticleError.swift
enum ArticleError: Error, Equatable, Sendable {
    case notFound
    case unauthorized
    case unavailable
    case unknown
}

// Domain error initialized from API error
extension ArticleError {
    init(from apiError: APIError) {
        switch apiError {
        case .unauthorized:
            self = .unauthorized
        case .httpError(404):
            self = .notFound
        case .networkUnavailable, .timeout:
            self = .unavailable
        default:
            self = .unknown
        }
    }
}

// Error decorator from domain error
extension ArticleError {
    func toDecorator() -> ErrorDecorator {
        switch self {
        case .notFound:
            return ErrorDecorator(
                title: String(localized: "error.notfound.title"),
                message: String(localized: "error.notfound.message"),
                isRetryable: false
            )
        case .unavailable:
            return .network
        default:
            return .generic
        }
    }
}

// Parallel detail fetching in Repository
func getPokemonList(limit: Int, offset: Int) async throws -> PokemonListRepositoryResult {
    let listResponse = try await remoteDataSource.fetchPokemonList(limit: limit, offset: offset)
    let pokemon = try await withThrowingTaskGroup(of: PokemonListModel?.self) { group in
        for result in listResponse.results {
            guard let id = result.extractedID else { continue }
            group.addTask {
                let detail = try await self.remoteDataSource.fetchPokemonDetail(id: id)
                return self.dtoMapper.mapToDomain(detail)
            }
        }
        var models: [PokemonListModel] = []
        for try await model in group {
            if let model { models.append(model) }
        }
        return models.sorted { $0.id < $1.id }
    }
    return PokemonListRepositoryResult(pokemon: pokemon, totalCount: listResponse.count, hasMore: listResponse.next != nil)
}

