struct ArticleLocalDataSourceImpl: ArticleLocalDataSource {
    private let executor: any ModelExecutor

    init(executor: any ModelExecutor) {
        self.executor = executor
    }

    func fetchAll() async throws -> [ArticleModel] {
        try await executor.perform {
            let descriptor = FetchDescriptor<ArticleSDModel>()
            let models = try executor.modelContext.fetch(descriptor)
            return models.map { $0.toDomain() }
        }
    }
}

